import json,sys
for line in sys.stdin:
    r=json.loads(line)
    print(r['target_id'], r['cde_level'], r['occupancy_basis'], r['nc_casualty_estimate'], r['ncv'], '|', r['approval_authority'], '|', r['weapon_class'], r['fuze'], 'TOT', r['tot_local'], '| nsl:', r['nsl_within_cer'], '| cmd:', r['cmd'])
""}

