import datetime
for d in ['2026-10-16','2026-10-18','2026-10-19','2026-10-20','2026-10-22']:
    print(d, datetime.date.fromisoformat(d).strftime('%a'))
# T-05 sensitivity: C3 fish market factor 0.09 (open-air 1.5 x 0.10 x delay 0.6)
base = 0.72+3.3+0.06  # C1+C2+C4 night ests
for occ in [4,5,10,11,15]:
    print('C3 occ',occ,'-> est', round(base+occ*0.09,2))
""}

